INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('1', 'TASK_ASSIGNED', 'Task Assigned Notification', 'New Task Assigned: {{task_title}} (Due: {{due_date}})', '<p>Dear {{user_name}},</p><p>You have been assigned a new operational task: <strong>{{task_title}}</strong>.</p><p>Related Application: <strong>{{application_number}}</strong><br>Applicant: <strong>{{applicant_name}}</strong><br>Deadline: <strong>{{due_date}}</strong></p><p><a href=\"{{action_url}}\">Click here to view task details</a></p>', '{{user_name}}, {{applicant_name}}, {{application_number}}, {{task_title}}, {{due_date}}, {{action_url}}', '1', '2026-08-24 09:55:00');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('2', 'TASK_DUE_SOON', 'Task Approaching SLA Deadline', 'Urgent: Task {{task_title}} Due Soon', '<p>Dear {{user_name}},</p><p>The task <strong>{{task_title}}</strong> for applicant <strong>{{applicant_name}}</strong> is approaching its SLA target.</p><p>Due Date: <strong>{{due_date}}</strong></p><p><a href=\"{{action_url}}\">Resolve and complete task</a></p>', '{{user_name}}, {{applicant_name}}, {{application_number}}, {{task_title}}, {{due_date}}, {{action_url}}', '1', '2026-08-24 09:55:00');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('3', 'TASK_OVERDUE', 'Task SLA Overdue Alert', 'CRITICAL SLA ALERT: Task {{task_title}} is Overdue', '<p>Attention {{user_name}},</p><p>The task <strong>{{task_title}}</strong> on application <strong>{{application_number}}</strong> is now <strong>OVERDUE</strong>.</p><p>Immediate operational intervention is required.</p><p><a href=\"{{action_url}}\">Take Immediate Action</a></p>', '{{user_name}}, {{applicant_name}}, {{application_number}}, {{task_title}}, {{due_date}}, {{action_url}}', '1', '2026-08-24 09:55:00');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('4', 'DOC_REJECTED', 'Document Verification Returned', 'Document Verification Failed: {{application_number}}', '<p>Dear {{applicant_name}},</p><p>Your uploaded document for application <strong>{{application_number}}</strong> could not be verified by our visa team.</p><p>Please upload a clear replacement copy to prevent embassy filing delays.</p><p><a href=\"{{action_url}}\">Upload Replacement Document</a></p>', '{{user_name}}, {{applicant_name}}, {{application_number}}, {{task_title}}, {{due_date}}, {{action_url}}', '1', '2026-08-24 09:55:00');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('5', 'APP_UPDATED', 'Application Lifecycle Stage Updated', 'Visa Progress Update: {{application_number}} is now in {{current_stage}}', '<p>Dear {{applicant_name}},</p><p>Your visa application <strong>{{application_number}}</strong> has successfully moved to the next lifecycle stage.</p><p>Next Milestone: <strong>{{next_action}}</strong></p><p><a href=\"{{action_url}}\">Track Real-Time Status</a></p>', '{{user_name}}, {{applicant_name}}, {{application_number}}, {{task_title}}, {{due_date}}, {{action_url}}', '1', '2026-08-24 09:55:00');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('6', 'APP_APPROVED', 'Visa Approved & Ready for Download', 'Congratulations! Visa Approved for {{applicant_name}} ({{application_number}})', '<p>Dear {{applicant_name}},</p><p>We are thrilled to confirm that your visa for <strong>{{destination_country}}</strong> has been granted and issued by consular authorities.</p><p><a href=\"{{action_url}}\">Download Official Visa e-Document</a></p>', '{{user_name}}, {{applicant_name}}, {{application_number}}, {{task_title}}, {{due_date}}, {{action_url}}', '1', '2026-08-24 09:55:00');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('7', 'PASSWORD_RESET', 'Administrative Password Reset', 'Your VISA TRACK Account Password Reset', '<p>Hello {{user_name}},</p><p>Your security credentials for the VISA TRACK Operations Portal have been reset by system administration.</p><p>Temporary Access Link: <a href=\"{{action_url}}\">Reset and choose your new password</a></p>', '{{user_name}}, {{applicant_name}}, {{application_number}}, {{task_title}}, {{due_date}}, {{action_url}}', '1', '2026-08-24 09:55:00');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('1464', 'APP_REGISTERED', 'Application Registered Confirmation', 'Visa Application Registered: {{application_number}} - {{destination_country}}', '<p>Dear {{customer_name}},</p><p>Your visa application <strong>{{application_number}}</strong> for <strong>{{visa_service}}</strong> has been successfully registered. You can track your progress online in real-time.</p><p>Next Step: {{next_action}}</p>', '{{customer_name}}, {{application_number}}, {{visa_service}}, {{destination_country}}, {{next_action}}', '1', '2026-08-25 12:26:40');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('1465', 'DOC_REQUIRED', 'Document Request Notice', 'Action Required: Additional Document Needed for {{application_number}}', '<p>Dear {{customer_name}},</p><p>To proceed with your application <strong>{{application_number}}</strong>, we require the following document: <strong>{{document_name}}</strong>.</p><p>Instructions: {{instructions}}</p><p>Please upload it via your customer portal before {{due_date}}.</p>', '{{customer_name}}, {{application_number}}, {{document_name}}, {{instructions}}, {{due_date}}', '1', '2026-08-25 12:26:40');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('1467', 'STAGE_UPDATED', 'Application Stage Progress Update', 'Status Update: Application {{application_number}} is now {{current_stage}}', '<p>Dear {{customer_name}},</p><p>Your visa application has progressed to stage: <strong>{{current_stage}}</strong>.</p><p>Next Action: {{next_action}}</p><p>Estimated Completion: {{expected_date}}</p>', '{{customer_name}}, {{application_number}}, {{current_stage}}, {{next_action}}, {{expected_date}}', '1', '2026-08-25 12:26:40');
INSERT INTO `email_templates` (`id`, `template_key`, `title`, `subject`, `body_html`, `placeholders`, `is_active`, `updated_at`) VALUES ('1468', 'VISA_APPROVED', 'Visa Approval & Final Download', 'Congratulations! Your Visa {{visa_number}} is APPROVED', '<p>Dear {{customer_name}},</p><p>We are delighted to inform you that your visa for <strong>{{destination_country}}</strong> has been approved!</p><p>Visa Number: <strong>{{visa_number}}</strong><br>Validity: {{validity}}</p><p>You can now download and print your official visa document from your customer portal.</p>', '{{customer_name}}, {{destination_country}}, {{visa_number}}, {{validity}}', '1', '2026-08-25 12:26:40');
INSERT INTO `notification_logs` (`id`, `event_type`, `recipient_type`, `recipient_id`, `recipient_name`, `recipient_email`, `recipient_phone`, `channel`, `template_name`, `subject`, `content_preview`, `idempotency_key`, `status`, `provider_message_id`, `request_payload`, `response_payload`, `error_message`, `retry_count`, `max_retries`, `next_retry_at`, `sent_at`, `created_at`) VALUES ('1', 'visa.test_queue', 'Applicant', NULL, 'Queue Test User', 'queue-test@example.com', NULL, 'Email', 'test_tmpl', NULL, NULL, 'queue_test_6a8bc8036485e', 'Sent', '1787545611.6a8bc80b6deee@Aqee', '{\"to\":\"queue-test@example.com\",\"name\":\"Queue Test User\",\"subject\":\"Queue Test Subject\",\"bodyHtml\":\"<p>Queue payload test<\\/p>\"}', NULL, NULL, '0', '3', NULL, '2026-08-24 06:26:52', '2026-08-24 09:56:52');
