ack.mstravelhub.com\",\"appUrl\":\"http:\\/\\/localhost:8000\",\"loginUrl\":\"http:\\/\\/localhost:8000\\/portal\\/login\",\"supportEmail\":\"support@mstravelhub.com\",\"applicantName\":\"Fault Isolation User\",\"recipient_email\":\"invalid-email\",\"recipientEmail\":\"invalid-email\",\"recipient_phone\":\"0771234567\",\"recipientPhone\":\"0771234567\",\"applicant_name\":\"Fault Isolation User\",\"application_number\":\"VISA-FAIL-01\",\"applicationNumber\":\"VISA-FAIL-01\"}}', NULL, 'Invalid or empty recipient email address: \'invalid-email\'', '0', '3', NULL, NULL, '2026-08-24 09:56:58');
