ountryName\":\"Canada\",\"visaType\":\"Tourist Visa\",\"passportNumber\":\"N1234567\"}}', '{\"messaging_product\":\"whatsapp\",\"contacts\":[{\"input\":\"94771234567\",\"wa_id\":\"94771234567\"}],\"messages\":[{\"id\":\"wamid.HBg3F8EC16C7B711FB6622980B9DC14==\"}],\"simulated\":true}', NULL, '0', '3', NULL, '2026-08-24 06:27:54', '2026-08-24 09:57:54');
