\\/li><li>Electronic devices and luggage may not be permitted inside the consular premises.<\\/li><\\/ul><p style=\\\"text-align: center; margin: 25px 0;\\\"><a href=\\\"{{actionUrl}}\\\" style=\\\"background: #0284c7; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\\\">View Appointment Slip<\\/a><\\/p>\",\"data\":{\"companyName\":\"MS Travel Hub Global Visa Services\",\"companyEmail\":\"notifications@mstravelhub.com\",\"companyPhone\":\"+94 11 234 5678\",\"companyWebsite\":\"https:\\/\\/visatrack.mstravelhub.com\",\"appUrl\":\"http:\\/\\/localhost:8000\",\"loginUrl\":\"http:\\/\\/localhost:8000\\/portal\\/login\",\"supportEmail\":\"support@mstravelhub.com\",\"applicantName\":\"Test Applicant\",\"application_id\":\"1\",\"applicationId\":\"1\",\"customer_id\":\"1\",\"customerId\":\"1\",\"recipient_email\":\"test-applicant@example.com\",\"recipientEmail\":\"test-applicant@example.com\",\"recipient_phone\":\"0771234567\",\"recipientPhone\":\"0771234567\",\"applicationNumber\":\"VISA-2026-0001\",\"appointmentType\":\"Biometrics & Consular Interview\",\"interviewDate\":\"2026-09-15\",\"interviewTime\":\"10:30 AM\",\"centerName\":\"VFS Global Colombo Center\",\"locationAddress\":\"World Trade Center, Colombo\"}}', NULL, NULL, '0', '3', NULL, '2026-08-24 06:28:03', '2026-08-24 09:58:03');
