recipient_phone\":\"0771234567\",\"recipientPhone\":\"0771234567\",\"applicationNumber\":\"VISA-2026-0001\",\"appointmentType\":\"Biometrics & Consular Interview\",\"interviewDate\":\"2026-09-15\",\"interviewTime\":\"10:30 AM\",\"centerName\":\"VFS Global Colombo Center\",\"locationAddress\":\"World Trade Center, Colombo\"}}', '{\"messaging_product\":\"whatsapp\",\"contacts\":[{\"input\":\"94771234567\",\"wa_id\":\"94771234567\"}],\"messages\":[{\"id\":\"wamid.HBg1DEFF0FED90D1C47C63F11915733==\"}],\"simulated\":true}', NULL, '0', '3', NULL, '2026-08-24 06:28:03', '2026-08-24 09:58:03');
INSERT INTO `notification_logs` (`id`, `event_type`, `recipient_type`, `recipient_id`, `recipient_name`, `recipient_email`, `recipient_phone`, `channel`, `template_name`, `subject`, `content_preview`, `idempotency_key`, `status`, `provider_message_id`, `request_payload`, `response_payload`, `error_message`, `retry_count`, `max_retries`, `next_retry_at`, `sent_at`, `created_at`) VALUES ('12', 'document.rejected', 'Staff', NULL, 'Valued Customer', 'test-applicant@example.com', NULL, 'Email', 'document_rejected_email', 'Document Verification Returned — Replacement Required (VISA-2026-0001)', 'Document Replacement RequiredDear Test Applicant,Our visa compliance officers have reviewed your uploaded document for application VISA-2026-0001 a...', 'evt_56aeeba845b117893583547b_email', 'Sent', '1787545687.6a8bc857759c2@Aqee', '{\"to\":\"test-applicant@example.com\",\"name\":\"Valued Customer\",\"subject\":\"Document Verification Returned \\u2014 Replacement Required ({{applicationNumber}})\",\"bodyHtml\":\"<h3>Document Replacement Required<\\/h3><p>Dear {{applicantName}},<\\/p><p>Our visa compliance officers have reviewed your uploaded document for application <strong>{{applicationNumber}}<\\/strong> and found that a replacement copy is required.<\\/p><div style=\\\"background: #fef2f2; border-left: 4px solid #dc2626; padding: 15px; margin: 15px 0;\\\"><p style=\\\"margin: 0 0 8px 0;\\\"><strong>Document:<\\/strong> {{documentName}}<\\/p><p style=\\\"margin: 0;\\\"><strong>Issue \\/ Reason:<\\/strong> {{rejectionReason}}<\\/p><\\/div><p>Please upload a high-resolution, full-page replacement copy immediately to avoid delays in embassy filing.<\\/p><p style=\\\"text-align: center; margin: 25px 0;\\\"><a href=\\\"{{actionUrl}}\\\" style=\\\"background: #dc2626; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\\\">Upload Replacement Document<\\/a><\\/p>\",\"data\":{\"companyName\":\"MS Travel Hub Global Visa Services\",\"companyEmail\":\"notifications@mstravelhub.com\",\"companyPhone\":\"+94 11 234 5678\",\"companyWebsite\":\"https:\\/\\/visatrack.mstravelhub.com\",\"appUrl\":\"http:\\/\\/localhost:8000\",\"loginUrl\":\"http:\\/\\/localhost:8000\\/portal\\/login\",\"supportEmail\":\"support@mstravelhub.com\",\"applicantName\":\"Test Applicant\",\"application_id\":\"1\",\"applicationId\":\"1\",\"customer_id\":\"1\",\"customerId\":\"1\",\"recipient_email\":\"test-applicant@example.com\",\"recipientEmail\":\"test-applicant@example.com\",\"recipient_phone\":\"0771234567\",\"recipientPhone\":\"0771234567\",\"applicationNumber\":\"VISA-2026-0001\",\"documentName\":\"Bank Statement (Last 6 Months)\",\"rejectionReason\":\"Document scan is blurry and missing official bank stamp\"}}', NULL, NULL, '0', '3', NULL, '2026-08-24 06:28:11', '2026-08-24 09:58:11');
