mail\":\"notifications@mstravelhub.com\",\"companyPhone\":\"+94 11 234 5678\",\"companyWebsite\":\"https:\\/\\/visatrack.mstravelhub.com\",\"appUrl\":\"http:\\/\\/localhost:8000\",\"loginUrl\":\"http:\\/\\/localhost:8000\\/portal\\/login\",\"supportEmail\":\"support@mstravelhub.com\",\"applicantName\":\"Test Applicant\",\"application_id\":\"1\",\"applicationId\":\"1\",\"customer_id\":\"1\",\"customerId\":\"1\",\"recipient_email\":\"test-applicant@example.com\",\"recipientEmail\":\"test-applicant@example.com\",\"recipient_phone\":\"0771234567\",\"recipientPhone\":\"0771234567\",\"applicationNumber\":\"VISA-2026-0001\",\"paymentNumber\":\"REC-2026-00088\",\"amount\":\"1,250.00\",\"currency\":\"USD\",\"paymentMethod\":\"Bank Transfer\",\"paymentDate\":\"2026-08-24\"}}', NULL, NULL, '0', '3', NULL, '2026-08-24 06:28:19', '2026-08-24 09:58:19');
