\"paymentNumber\":\"REC-2026-00088\",\"amount\":\"1,250.00\",\"currency\":\"USD\",\"paymentMethod\":\"Bank Transfer\",\"paymentDate\":\"2026-08-24\"}}', '{\"messaging_product\":\"whatsapp\",\"contacts\":[{\"input\":\"94771234567\",\"wa_id\":\"94771234567\"}],\"messages\":[{\"id\":\"wamid.HBg6A1AA8C4D01678CE87072180173B==\"}],\"simulated\":true}', NULL, '0', '3', NULL, '2026-08-24 06:28:19', '2026-08-24 09:58:19');
