: bold; display: inline-block;\\\">Download Official Visa Document<\\/a><\\/p><p>We wish you a safe and successful journey!<\\/p>\",\"data\":{\"companyName\":\"MS Travel Hub Global Visa Services\",\"companyEmail\":\"notifications@mstravelhub.com\",\"companyPhone\":\"+94 11 234 5678\",\"companyWebsite\":\"https:\\/\\/visatrack.mstravelhub.com\",\"appUrl\":\"http:\\/\\/localhost:8000\",\"loginUrl\":\"http:\\/\\/localhost:8000\\/portal\\/login\",\"supportEmail\":\"support@mstravelhub.com\",\"applicantName\":\"Rahul Dev Sharma\",\"customerCode\":\"MSC-000001\",\"applicantEmail\":\"rahul.sharma@cloudtech.ae\",\"applicantPhone\":\"+971 55 123 4567\",\"nationality\":\"India\",\"application_id\":\"1\",\"applicationId\":\"1\",\"customer_id\":\"1\",\"customerId\":\"1\",\"recipient_email\":\"rahul.sharma@cloudtech.ae\",\"recipientEmail\":\"rahul.sharma@cloudtech.ae\",\"recipient_phone\":\"+971 55 123 4567\",\"recipientPhone\":\"+971 55 123 4567\",\"applicationNumber\":\"VISA-2026-0001\",\"countryName\":\"Canada\",\"visaType\":\"Tourist Visa\",\"passportNumber\":\"N1234567\"}}', NULL, NULL, '0', '3', NULL, '2026-08-25 07:44:01', '2026-08-25 11:14:01');
