INSERT INTO `notification_logs` (`id`, `event_type`, `recipient_type`, `recipient_id`, `recipient_name`, `recipient_email`, `recipient_phone`, `channel`, `template_name`, `subject`, `content_preview`, `idempotency_key`, `status`, `provider_message_id`, `request_payload`, `response_payload`, `error_message`, `retry_count`, `max_retries`, `next_retry_at`, `sent_at`, `created_at`) VALUES ('55', 'visa.approved', 'Applicant', '1', 'Rahul Dev Sharma', 'rahul.sharma@cloudtech.ae', NULL, 'Email', 'visa_approved_email', 'Congratulations! Your Visa Has Been Approved — MSV-2026-000001', 'Congratulations! Visa GrantedDear Rahul Dev Sharma,We are delighted to inform you that your visa application for United Arab Emirates (Employment V...', 'evt_55bb1af86f827eee15172414_email', 'Sent', '1787732751.6a8ea30f3da96@Aqee', '{\"to\":\"rahul.sharma@cloudtech.ae\",\"name\":\"Rahul Dev Sharma\",\"subject\":\"Congratulations! Your Visa Has Been Approved \\u2014 {{applicationNumber}}\",\"bodyHtml\":\"<h2 style=\\\"color: #16a34a;\\\">Congratulations! Visa Granted<\\/h2><p>Dear {{applicantName}},<\\/p><p>We are delighted to inform you that your visa application for <strong>{{countryName}} ({{visaType}})<\\/strong> has been <strong>APPROVED &amp; ISSUED<\\/strong> by consular authorities!<\\/p><div style=\\\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 15px; margin: 15px 0;\\\"><p style=\\\"margin: 0 0 8px 0;\\\"><strong>Application No:<\\/strong> {{applicationNumber}}<\\/p><p style=\\\"margin: 0 0 8px 0;\\\"><strong>Destination Country:<\\/strong> {{countryName}}<\\/p><p style=\\\"margin: 0;\\\"><strong>Passport Number:<\\/strong> {{passportNumber}}<\\/p><\\/div><p>Your official visa document and stamped confirmation are now available for secure download in your portal.<\\/p><p style=\\\"text-align: center; margin: 25px 0;\\\"><a href=\\\"{{actionUrl}}\\\" style=\\\"background: #16a34a; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\\\">Download Official Visa Document<\\/a><\\/p><p>We wish you a safe and successful journey!<\\/p>\",\"data\":{\"companyName\":\"MS Travel Hub Global Visa Services\",\"companyEmail\":\"notifications@mstravelhub.com\",\"companyPhone\":\"+94 11 234 5678\",\"companyWebsite\":\"https:\\/\\/visatrack.mstravelhub.com\",\"appUrl\":\"http:\\/\\/localhost:8000\",\"loginUrl\":\"http:\\/\\/localhost:8000\\/portal\\/login\",\"supportEmail\":\"support@mstravelhub.com\",\"applicantName\":\"Rahul Dev Sharma\",\"customerCode\":\"MSC-000001\",\"applicantEmail\":\"rahul.sharma@cloudtech.ae\",\"applicantPhone\":\"+971 55 123 4567\",\"nationality\":\"India\",\"userName\":\"Sarah Jenkins\",\"staffName\":\"Sarah Jenkins\",\"staffEmail\":\"manager@visatrack.com\",\"applicationNumber\":\"MSV-2026-000001\",\"countryName\":\"United Arab Emirates\",\"visaType\":\"Employment Visa\",\"currentStage\":\"In Process\",\"status\":\"In Process\",\"passportNumber\":\"Z6543219\",\"actionUrl\":\"http:\\/\\/localhost:8000\\/portal\\/dashboard\",\"application_id\":\"1\",\"applicationId\":\"1\",\"customer_id\":\"1\",\"customerId\":\"1\",\"application_number\":\"MSV-2026-000001\",\"current_stage\":\"In Process\",\"amount\":\"350.00\",\"currency\":\"USD\",\"paymentNumber\":\"RCP-TEST-001\",\"paymentMethod\":\"Stripe\"}}', NULL, NULL, '0', '3', NULL, '2026-08-26 10:25:52', '2026-08-26 13:55:52');
