INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('1', 'applicant.registered', 'Email', 'applicant_registered_email', 'Welcome to {{companyName}} — Registration Confirmed', '<h3>Welcome to {{companyName}}</h3><p>Dear {{applicantName}},</p><p>Your applicant profile has been successfully created in our visa management system.</p><p><strong>Customer ID:</strong> {{customerCode}}<br><strong>Registered Mobile:</strong> {{applicantPhone}}<br><strong>Email:</strong> {{applicantEmail}}</p><p>You can now access your customer self-service portal at any time to track your visa applications and upload required documents.</p><p style=\"text-align: center; margin: 25px 0;\"><a href=\"{{loginUrl}}\" style=\"background: #0284c7; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\">Access Applicant Portal</a></p><p>If you have any questions, our visa consulting team is here to assist you.</p>', NULL, 'en_US', 'applicantName, customerCode, applicantEmail, applicantPhone, companyName, loginUrl, supportEmail', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('2', 'interview.scheduled', 'Email', 'interview_scheduled_email', 'Interview / Embassy Appointment Scheduled — {{applicationNumber}}', '<h3>Embassy / Visa Appointment Confirmation</h3><p>Dear {{applicantName}},</p><p>Your appointment for <strong>{{countryName}} ({{visaType}})</strong> has been officially scheduled.</p><div style=\"background: #f8fafc; border-left: 4px solid #0284c7; padding: 15px; margin: 15px 0;\"><p style=\"margin: 0 0 8px 0;\"><strong>Appointment Type:</strong> {{appointmentType}}</p><p style=\"margin: 0 0 8px 0;\"><strong>Date:</strong> {{interviewDate}}</p><p style=\"margin: 0 0 8px 0;\"><strong>Time:</strong> {{interviewTime}}</p><p style=\"margin: 0 0 8px 0;\"><strong>Center / Embassy:</strong> {{centerName}}</p><p style=\"margin: 0;\"><strong>Location Address:</strong> {{locationAddress}}</p></div><p><strong>Important Instructions:</strong></p><ul><li>Please arrive at the center at least 15 minutes prior to your scheduled time.</li><li>Bring your original passport, appointment confirmation letter, and all original supporting documents.</li><li>Electronic devices and luggage may not be permitted inside the consular premises.</li></ul><p style=\"text-align: center; margin: 25px 0;\"><a href=\"{{actionUrl}}\" style=\"background: #0284c7; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\">View Appointment Slip</a></p>', NULL, 'en_US', 'applicantName, applicationNumber, countryName, visaType, appointmentType, interviewDate, interviewTime, centerName, locationAddress, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('3', 'interview.rescheduled', 'Email', 'interview_rescheduled_email', 'Appointment Rescheduled: {{applicationNumber}} (New Date: {{interviewDate}})', '<h3>Visa Appointment Rescheduled</h3><p>Dear {{applicantName}},</p><p>Please note that your appointment for application <strong>{{applicationNumber}}</strong> has been rescheduled.</p><div style=\"background: #fffbeb; border-left: 4px solid #f59e0b; padding: 15px; margin: 15px 0;\"><p style=\"margin: 0 0 8px 0;\"><strong>New Date:</strong> {{interviewDate}}</p><p style=\"margin: 0 0 8px 0;\"><strong>New Time:</strong> {{interviewTime}}</p><p style=\"margin: 0 0 8px 0;\"><strong>Center / Embassy:</strong> {{centerName}}</p><p style=\"margin: 0;\"><strong>Location:</strong> {{locationAddress}}</p></div><p><a href=\"{{actionUrl}}\">Download updated appointment confirmation</a></p>', NULL, 'en_US', 'applicantName, applicationNumber, interviewDate, interviewTime, centerName, locationAddress, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('4', 'visa.created', 'Email', 'visa_created_email', 'Visa Application Created: {{applicationNumber}} — {{countryName}}', '<h3>Visa Application Successfully Opened</h3><p>Dear {{applicantName}},</p><p>A new visa application has been registered for you at {{companyName}}.</p><p><strong>Application Number:</strong> {{applicationNumber}}<br><strong>Destination:</strong> {{countryName}}<br><strong>Visa Category:</strong> {{visaType}}<br><strong>Current Stage:</strong> {{currentStage}}</p><p>Please complete any pending checklist documents to expedite consular submission.</p><p style=\"text-align: center; margin: 25px 0;\"><a href=\"{{actionUrl}}\" style=\"background: #0284c7; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\">Track Application Status</a></p>', NULL, 'en_US', 'applicantName, applicationNumber, countryName, visaType, currentStage, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('5', 'visa.stage_changed', 'Email', 'visa_stage_changed_email', 'Visa Status Update: {{applicationNumber}} is now in {{currentStage}}', '<h3>Visa Lifecycle Progress Update</h3><p>Dear {{applicantName}},</p><p>Your visa application <strong>{{applicationNumber}}</strong> for <strong>{{countryName}}</strong> has advanced to a new stage.</p><div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 15px; margin: 15px 0;\"><p style=\"margin: 0 0 8px 0;\"><strong>Current Stage:</strong> {{currentStage}}</p><p style=\"margin: 0 0 8px 0;\"><strong>Application Status:</strong> {{status}}</p><p style=\"margin: 0;\"><strong>Next Planned Action:</strong> {{nextAction}}</p></div><p style=\"text-align: center; margin: 25px 0;\"><a href=\"{{actionUrl}}\" style=\"background: #16a34a; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\">View Real-Time Progress</a></p>', NULL, 'en_US', 'applicantName, applicationNumber, countryName, currentStage, status, nextAction, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('6', 'visa.approved', 'Email', 'visa_approved_email', 'Congratulations! Your Visa Has Been Approved — {{applicationNumber}}', '<h2 style=\"color: #16a34a;\">Congratulations! Visa Granted</h2><p>Dear {{applicantName}},</p><p>We are delighted to inform you that your visa application for <strong>{{countryName}} ({{visaType}})</strong> has been <strong>APPROVED &amp; ISSUED</strong> by consular authorities!</p><div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 15px; margin: 15px 0;\"><p style=\"margin: 0 0 8px 0;\"><strong>Application No:</strong> {{applicationNumber}}</p><p style=\"margin: 0 0 8px 0;\"><strong>Destination Country:</strong> {{countryName}}</p><p style=\"margin: 0;\"><strong>Passport Number:</strong> {{passportNumber}}</p></div><p>Your official visa document and stamped confirmation are now available for secure download in your portal.</p><p style=\"text-align: center; margin: 25px 0;\"><a href=\"{{actionUrl}}\" style=\"background: #16a34a; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\">Download Official Visa Document</a></p><p>We wish you a safe and successful journey!</p>', NULL, 'en_US', 'applicantName, applicationNumber, countryName, visaType, passportNumber, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('7', 'visa.rejected', 'Email', 'visa_rejected_email', 'Important Notice Regarding Your Visa Application — {{applicationNumber}}', '<h3 style=\"color: #dc2626;\">Visa Application Decision Notice</h3><p>Dear {{applicantName}},</p><p>We regret to inform you that consular authorities have returned a decision of refusal for visa application <strong>{{applicationNumber}}</strong> ({{countryName}}).</p><div style=\"background: #fef2f2; border-left: 4px solid #dc2626; padding: 15px; margin: 15px 0;\"><p style=\"margin: 0;\"><strong>Reason / Notes:</strong> {{decisionNotes}}</p></div><p>Our senior visa consulting team is currently reviewing your refusal grounds to advise on appeals, administrative review, or re-application options.</p><p><a href=\"{{actionUrl}}\">Review consular refusal details</a></p>', NULL, 'en_US', 'applicantName, applicationNumber, countryName, decisionNotes, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('8', 'document.rejected', 'Email', 'document_rejected_email', 'Document Verification Returned — Replacement Required ({{applicationNumber}})', '<h3>Document Replacement Required</h3><p>Dear {{applicantName}},</p><p>Our visa compliance officers have reviewed your uploaded document for application <strong>{{applicationNumber}}</strong> and found that a replacement copy is required.</p><div style=\"background: #fef2f2; border-left: 4px solid #dc2626; padding: 15px; margin: 15px 0;\"><p style=\"margin: 0 0 8px 0;\"><strong>Document:</strong> {{documentName}}</p><p style=\"margin: 0;\"><strong>Issue / Reason:</strong> {{rejectionReason}}</p></div><p>Please upload a high-resolution, full-page replacement copy immediately to avoid delays in embassy filing.</p><p style=\"text-align: center; margin: 25px 0;\"><a href=\"{{actionUrl}}\" style=\"background: #dc2626; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\">Upload Replacement Document</a></p>', NULL, 'en_US', 'applicantName, applicationNumber, documentName, rejectionReason, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('9', 'payment.received', 'Email', 'payment_received_email', 'Payment Received & Receipt Generated — {{paymentNumber}}', '<h3>Payment Receipt Confirmation</h3><p>Dear {{applicantName}},</p><p>We have successfully received and processed your payment for application <strong>{{applicationNumber}}</strong>.</p><div style=\"background: #f8fafc; border-left: 4px solid #0284c7; padding: 15px; margin: 15px 0;\"><p style=\"margin: 0 0 8px 0;\"><strong>Receipt / Payment No:</strong> {{paymentNumber}}</p><p style=\"margin: 0 0 8px 0;\"><strong>Amount Paid:</strong> {{amount}} {{currency}}</p><p style=\"margin: 0 0 8px 0;\"><strong>Payment Method:</strong> {{paymentMethod}}</p><p style=\"margin: 0;\"><strong>Date:</strong> {{paymentDate}}</p></div><p style=\"text-align: center; margin: 25px 0;\"><a href=\"{{receiptUrl}}\" style=\"background: #0284c7; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;\">Download Official Receipt</a></p>', NULL, 'en_US', 'applicantName, applicationNumber, paymentNumber, amount, currency, paymentMethod, paymentDate, receiptUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('10', 'applicant.registered', 'WhatsApp', 'applicant_welcome_wa', NULL, 'Hello {{applicantName}},\n\nWelcome to {{companyName}}! Your applicant profile has been created.\n\nCustomer Code: {{customerCode}}\n\nYou can track your visa application status on our customer portal: {{loginUrl}}\n\nThank you for choosing {{companyName}}.', 'applicant_welcome', 'en_US', 'applicantName, companyName, customerCode, loginUrl', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('11', 'interview.scheduled', 'WhatsApp', 'interview_scheduled_wa', NULL, 'Hello {{applicantName}},\n\nYour visa appointment has been scheduled.\n\nApplication No: {{applicationNumber}}\nDate: {{interviewDate}}\nTime: {{interviewTime}}\nCenter: {{centerName}}\nLocation: {{locationAddress}}\n\nPlease arrive 15 minutes early with all original documents.\n\n{{companyName}}', 'interview_scheduled', 'en_US', 'applicantName, applicationNumber, interviewDate, interviewTime, centerName, locationAddress, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('12', 'interview.rescheduled', 'WhatsApp', 'interview_rescheduled_wa', NULL, 'Hello {{applicantName}},\n\nYour visa appointment for application {{applicationNumber}} has been rescheduled.\n\nNew Date: {{interviewDate}}\nNew Time: {{interviewTime}}\nCenter: {{centerName}}\n\nPlease check your portal for the updated appointment slip.\n\n{{companyName}}', 'interview_rescheduled', 'en_US', 'applicantName, applicationNumber, interviewDate, interviewTime, centerName, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('13', 'visa.stage_changed', 'WhatsApp', 'visa_stage_changed_wa', NULL, 'Hello {{applicantName}},\n\nYour visa application status has been updated.\n\nApplication No: {{applicationNumber}}\nCurrent Stage: {{currentStage}}\nStatus: {{status}}\n\nPlease log in to your portal for full details: {{actionUrl}}\n\n{{companyName}}', 'visa_status_update', 'en_US', 'applicantName, applicationNumber, currentStage, status, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('14', 'visa.approved', 'WhatsApp', 'visa_approved_wa', NULL, '🎉 Congratulations {{applicantName}}!\n\nYour visa for {{countryName}} has been APPROVED and issued!\n\nApplication No: {{applicationNumber}}\nPassport: {{passportNumber}}\n\nPlease log in to download your official e-visa document: {{actionUrl}}\n\n{{companyName}}', 'visa_approved', 'en_US', 'applicantName, countryName, applicationNumber, passportNumber, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('15', 'visa.rejected', 'WhatsApp', 'visa_rejected_wa', NULL, 'Hello {{applicantName}},\n\nAn update is available regarding your visa application {{applicationNumber}} for {{countryName}}.\n\nPlease log in to your portal to review the decision details and next steps: {{actionUrl}}\n\n{{companyName}}', 'visa_decision_notice', 'en_US', 'applicantName, applicationNumber, countryName, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('16', 'document.rejected', 'WhatsApp', 'document_rejected_wa', NULL, 'Hello {{applicantName}},\n\nA replacement document is required for your visa application {{applicationNumber}}.\n\nDocument: {{documentName}}\nReason: {{rejectionReason}}\n\nPlease upload a replacement copy promptly: {{actionUrl}}\n\n{{companyName}}', 'document_required', 'en_US', 'applicantName, applicationNumber, documentName, rejectionReason, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('17', 'payment.received', 'WhatsApp', 'payment_received_wa', NULL, 'Hello {{applicantName}},\n\nWe have received your payment of {{amount}} {{currency}} for application {{applicationNumber}}.\n\nReceipt No: {{paymentNumber}}\nDate: {{paymentDate}}\n\nDownload receipt: {{receiptUrl}}\n\n{{companyName}}', 'payment_received', 'en_US', 'applicantName, amount, currency, applicationNumber, paymentNumber, paymentDate, receiptUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
INSERT INTO `notification_templates` (`id`, `event_type`, `channel`, `template_name`, `subject`, `content`, `provider_template_id`, `language_code`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES ('18', 'placement.confirmed', 'WhatsApp', 'placement_confirmed_wa', NULL, 'Hello {{applicantName}},\n\nYour overseas placement offer for application {{applicationNumber}} has been confirmed!\n\nPosition: {{position}}\nLocation: {{location}}\n\nPlease log in to your portal to review your placement agreement: {{actionUrl}}\n\n{{companyName}}', 'placement_confirmed', 'en_US', 'applicantName, applicationNumber, position, location, actionUrl, companyName', '1', '2026-08-24 09:55:58', '2026-08-24 09:55:58');
